  str_junior_skin_draw_cn16_intro_head_2 = "교환센터",
  str_junior_skin_draw_cn16_intro_body_2 = "○ 소원의 고치는 교환센터에서 진예 알터 코스튬 <color=#063c8e>[태평천하]</color>, 알터 전용 프레임, 알터 전용 아바타, 특별 소집 스타 마커, 스타 마커 등 보상으로 교환할 수 있습니다.\n○ 소원의 고치 <color=#d70500>198</color>개 수집 시 진예 알터 코스튬 <color=#063c8e>[태평천하]</color>로 1회 교환할 수 있으며, 해당 코스튬을 중복 획득 시 소원의 고치 <color=#d70500>100</color>개로 전환됩니다.",
  str_junior_skin_draw_cn16_intro_head_3 = "이벤트 종료",
  str_junior_skin_draw_cn16_intro_body_3 = "○ 본 이벤트 종료 후, 사용하지 않은 소원의 힘 아이템은 <color=#d70500>1:40</color>의 비율에 따라 루맘버로 전환되며, 사용하지 않은 소원의 고치는 <color=#d70500>1:3000</color>의 비율에 따라 나이티움으로 전환됩니다. 이상의 전환 보상은 이벤트 종료 후 게임 내 우편을 통해 지급됩니다.",
  str_junior_skin_draw_cn16_probability_title = "[태평천하] 소원 이벤트 확률 설명",
  str_junior_skin_draw_cn16_probability_head = "이벤트 규칙",
  str_junior_skin_draw_cn16_probability_body = "본 이벤트에서 소원을 진행할 때마다 다음 고정 확률에 따라 랜덤 보상을 획득하며, 모든 보상은 중복 획득할 수 있습니다. 모든 보상을 획득할 확률의 합은 늘 1로 일정합니다.",
  str_junior_skin_draw_cn16_probability_txt1 = "본 이벤트에서 소원을 진행할 때마다 다음 고정 확률에 따라 랜덤 보상을 획득합니다.",
  str_junior_skin_draw_cn16_gift_txt = "소원의 힘×{1}",
  str_junior_skin_draw_cn16_7000512_name = "태평천하",
  str_junior_skin_draw_cn16_7000512_desc = "「그대를 위해 엮은 액막이 끈, 오색으로 천 개의 봄을 바라노라.」\n용주의 오색절, 당신과 진예는 「어떤 소원」을 찾는 모험을 떠났다. 세상 사람들은 누구나 바라는 것이 있는 법, 그리고 당신에게 다시 한번 선녀용왕 앞에서 두 손을 모아 기도할 기회가 주어진다면, 이번에는 과연 어떤 소원을 빌게 될까.",
  str_junior_skin_draw_n47_title = "여명의 품격",
  str_junior_skin_draw_n47_sub_title = "여명의 품격",
  str_junior_skin_draw_n47_intro_title = "여명의 품격 규칙 설명",
  str_junior_skin_draw_n47_intro_head_1 = "소원 이벤트 규칙",
  str_junior_skin_draw_n47_intro_body_1 = "○ [소원의 힘] 아이템을 사용해 소원을 진행할 수 있습니다. 소원의 힘은 라피스를 소모해 구매하거나 정가 구매로 획득할 수 있습니다.\n○ 매회 소원 비용은 고정됩니다. 소원 <color=#d70500>1</color>회 진행 시 소원의 힘을 <color=#d70500>1</color>개 소모해 소원 보상 <color=#d70500>1</color>개를 획득하며, 소원 <color=#d70500>10</color>회 진행 시 소원의 힘을 <color=#d70500>10</color>개 소모해 소원 보상 <color=#d70500>10</color>개를 획득합니다.\n○ 소원을 진행할 때마다 랜덤으로 다음 보상 중 1개를 획득합니다.\n라인하르트 알터 코스튬 <color=#063c8e>[여명의 품격]</color>\n특별 소집 스타 마커*<color=#d70500>1</color>\n루맘버*<color=#d70500>50</color>\n프리즘*<color=#d70500>50</color>\n하트스톤*<color=#d70500>50</color>\n소원의 고치*<color=#d70500>20</color>\n소원의 고치*<color=#d70500>15</color>\n소원의 고치*<color=#d70500>10</color>\n소원의 고치*<color=#d70500>8</color>\n소원의 고치*<color=#d70500>5</color>\n소원의 고치*<color=#d70500>3</color>\n소원의 고치*<color=#d70500>2</color>",
  str_junior_skin_draw_n47_intro_head_2 = "교환센터",
  str_junior_skin_draw_n47_intro_body_2 = "○ 소원의 고치는 교환센터에서 라인하르트 알터 코스튬 <color=#063c8e>[여명의 품격]</color>, 알터 전용 프레임, 알터 전용 아바타, 특별 소집 스타 마커, 스타 마커 등 보상으로 교환할 수 있습니다.\n○ 소원의 고치 <color=#d70500>198</color>개 수집 시 라인하르트 알터 코스튬 <color=#063c8e>[여명의 품격]</color>으로 1회 교환할 수 있으며, 해당 코스튬을 중복 획득 시 소원의 고치 <color=#d70500>100</color>개로 전환됩니다.",
  str_junior_skin_draw_n47_intro_head_3 = "이벤트 종료",
