  str_junior_skin_draw_n47_probability_title = "[여명의 품격] 알터 이벤트 확률 설명",
  str_junior_skin_draw_n47_probability_head = "이벤트 규칙",
  str_junior_skin_draw_n47_probability_body = "본 이벤트에서 소원을 진행할 때마다 다음 고정 확률에 따라 랜덤 보상을 획득하며, 모든 보상은 중복 획득할 수 있습니다. 모든 보상을 획득할 확률의 합은 늘 1로 일정합니다.",
  str_junior_skin_draw_n47_probability_txt1 = "본 이벤트에서 소원을 진행할 때마다 다음 고정 확률에 따라 랜덤 보상을 획득합니다.",
  str_junior_skin_draw_n47_gift_txt = "소원의 힘×{1}",
  str_junior_skin_draw_n47_7000512_name = "여명의 품격",
  str_junior_skin_draw_n47_7000512_desc = "「정장」, 그것은 일종의 괴물이다. 녀석은 소심하고, 무대를 두려워하고, 스스로에게 회의적인 사람들을 집어삼킨다. 그러나 라인하르트에게는 머리를 숙이고, 오직 그녀의 강인함과 우아함을 강조하려 할 뿐이다.\n절묘한 테일러링은 체형에 딱 맞아 그녀의 잘 단련된 몸의 모든 부분에 감탄하게 만든다. 깔끔한 스타일은 결코 유행에 뒤처지지 않으며, 그녀의 몸에서 확고한 의지가 느껴지게 만든다. 이는 그녀가 시대의 흐름을 선도하려 하는 사람이기 때문이다.\n오늘 밤, 정장은 그녀의 전투복이고, 와인잔은 그녀의 창이다. 단단히 무장하고 연회로 전진하는 그녀는 일루미나의 대원수이자 미래를 주시하는 외교가다.",
